"""Report templates."""
import os

from vault.core.config import TEMPLATES_DIR


def load_template(name: str) -> str:
    if '..' in name or os.path.isabs(name): # Enforce no path traversal or absolute paths
        raise ValueError("Invalid template name provided.")
    path = os.path.join(TEMPLATES_DIR, name)
    # Additional check to ensure the resulting path is still within TEMPLATES_DIR
    if not os.path.abspath(path).startswith(os.path.abspath(TEMPLATES_DIR)):
        raise ValueError("Template path escapes the allowed directory.")
    if not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path) as handle:
        return handle.read()


def render(name: str, title: str) -> str:
    return load_template(name).replace("{{title}}", title)

