"""Link previews for documents."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_FETCH_HOSTS
from vault.core.net import http_get
import os


def preview(url: str) -> str:
    parts = urlparse(url)
    if parts.scheme != "https" or parts.hostname not in ALLOWED_FETCH_HOSTS:
        raise PermissionError("host not allowed")
    return http_get(parts.hostname, parts.path or "/")[:200]


def read_asset(url: str) -> str:
    parts = urlparse(url)
    if parts.scheme == "file":
        # Enforce invariant: path must be within a safe base directory and not traverse upwards
        base_dir = os.path.abspath("/var/vault/assets")
        requested_path = os.path.abspath(parts.path)

        if not requested_path.startswith(base_dir + os.sep) and requested_path != base_dir:
            raise PermissionError("file path outside allowed base directory")

        try:
            with open(requested_path, errors="ignore") as handle:
                return handle.read()[:4000]
        except FileNotFoundError:
            raise FileNotFoundError("asset file not found")
        except Exception:
            # Catch other potential IO errors during reading
            raise IOError("failed to read asset file")

    if parts.hostname not in ALLOWED_FETCH_HOSTS:
        raise PermissionError("host not allowed")
    return http_get(parts.hostname, parts.path or "/")[:200]

"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(target: str) -> str:
    if not target: 
        return "/home"
    parts = urlparse(target)
    # Check if it looks like a relative path (starts with / but not //)
    if parts.scheme == "" and parts.netloc == "" and target.startswith("/") and not target.startswith("//"):
        return target
    # Check if it's an absolute URL and the host is allowed
    if parts.scheme in ("http", "https") and parts.netloc in ALLOWED_REDIRECT_HOSTS:
        return target
    # Otherwise, it's potentially malicious or invalid, default to /home
    return "/home"


def logout_target(target: str) -> str:
    parts = urlparse(target)
    if parts.scheme == "" and parts.netloc == "" and target.startswith("/") and not target.startswith("//"):
        return target
    if parts.scheme == "https" and parts.hostname in ALLOWED_REDIRECT_HOSTS:
        return target
    return "/home"

