import base64
import pickle


def load_prefs(blob: str) -> dict:
    try:
        decoded_data = base64.b64decode(blob)
    except Exception:
        raise ValueError("Invalid base64 encoding")

    try:
        data = pickle.loads(decoded_data)
    except pickle.UnpicklingError:
        raise ValueError("Invalid serialized data format")

    if not isinstance(data, dict):
        raise ValueError("Deserialized data must be a dictionary")

    return data

