    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    user = User(name)
    # Enforce that the template is a simple string and does not contain signs of code execution.
    # We check for common indicators of code injection attempts.
    if 'def ' in template or 'import ' in template or '__' in template and ('.__globals__' in template or '.__builtins__' in template):
        raise ValueError("Template contains suspicious code constructs.")
    return template.format(user=user)
